    "When hurt since its last tactic": "마지막 책략 이후 다쳤을 때",
    "When it is the last enemy": "마지막 적일 때",
    "When two or more other enemies are in play": "다른 적이 둘 이상 있을 때",
    "Starting inventory": "시작 창고",
    "Your first interaction": "첫 번째 상호작용",
    "Every map starts with the starting room. Create it with the button on the left.": "모든 맵은 시작 방으로 시작해요. 왼쪽 버튼으로 만드세요.",
    "Pick a tile in the palette and put it on the board; press R to rotate it. For now, place two different tiles: they will be taken out of the box and set up during the game.": "팔레트에서 타일을 골라 보드에 놓으세요. R을 누르면 회전해요. 지금은 서로 다른 타일 두 개를 놓으세요. 게임 중에 상자에서 꺼내 배치할 거예요.",
    "The Hero button (H) sets the starting squares of our adventurers. Select 2 to 4 squares in the starting room.": "영웅 버튼(H)으로 모험가들의 시작 칸을 정해요. 시작 방에서 칸을 2~4개 선택하세요.",
    "To reveal the map little by little, we need to create a new room. It appears when an object is used, by programming a trigger that opens a room. Let us try it: click the Object button (O) and pick a door. Then add an “Open a room” trigger.": "맵을 조금씩 드러내려면 새 방을 만들어야 해요. 새 방은 오브젝트를 사용할 때 나타나며, 방을 여는 트리거를 프로그래밍해서 만들어요. 해 봐요. 오브젝트 버튼(O)을 누르고 문을 고르세요. 그런 다음 “방 열기” 트리거를 추가하세요.",
    "You have created your first interaction with the scenery. In the game, the hero will open the door and release the tiles of the next room. Now, let us fill that room: put a chest in a room and program a trigger that gives items to the players (the other buttons and triggers wait for this).": "배경과의 첫 번째 상호작용을 만들었어요. 게임에서 영웅이 문을 열면 다음 방의 타일이 풀려요. 이제 그 방을 채워 봐요. 방에 상자를 놓고 플레이어에게 아이템을 주는 트리거를 프로그래밍하세요 (다른 버튼과 트리거는 이것을 기다려요).",
    "📂 Import a save of the game (.sav)": "📂 게임 저장 파일 가져오기 (.sav)",
    "Clear all": "모두 지우기",
    "Search an item…": "아이템 검색…",
    "Only what the party has": "파티가 가진 것만",
    "skills": "기술",
    "Others": "기타",
    "Clear the whole starting inventory?": "시작 창고를 모두 지울까요?",
    "Replace the starting inventory with the one of this save?": "시작 창고를 이 저장 파일의 것으로 바꿀까요?",
    "Imported from the save": "저장 파일에서 가져옴",
    "This file is not a save of the game.": "이 파일은 게임 저장 파일이 아니에요.",
    "For a party of veterans: what it already holds when the campaign starts, won in earlier battles. The party receives it when the campaign begins. Items come from the Workshop (Items and Weapons tabs), the skills from the Skills tab (or the game’s). The item pools of the generated maps leave out the unique items the party already has, and the game never gives an item twice.": "베테랑 파티용이에요. 캠페인을 시작할 때 이미 가지고 있는 것, 이전 전투에서 얻은 것이에요. 파티는 캠페인이 시작될 때 이것을 받아요. 아이템은 워크숍(아이템 탭과 무기 탭)에서, 기술은 기술 탭(또는 게임의 기술)에서 와요. 생성된 맵의 아이템 풀에서는 파티가 이미 가진 고유 아이템이 빠지고, 게임은 같은 아이템을 두 번 주지 않아요.",
    "Starting gold": "시작 골드",
    "The Workshop has no items yet: import them in the Items tab.": "워크숍에 아직 아이템이 없어요. 아이템 탭에서 가져오세요.",
