    "This browser cannot write into folders; use Chrome or Edge.": "이 브라우저는 폴더에 쓸 수 없어요. Chrome이나 Edge를 쓰세요.",
    "This browser does not let the page write into a folder. Use Chrome or Edge.": "이 브라우저는 페이지가 폴더에 쓰는 것을 허용하지 않아요. Chrome이나 Edge를 쓰세요.",
    "Language / Idioma": "언어 / Idioma",
