    "Assemble the new weapon": "새 무기 조립",
    "This piece has no picture.": "이 부품에는 그림이 없어요.",
    "Forged: the three pieces now have their own pictures, laid out as you assembled them.": "단조 완료: 세 부품이 이제 조립한 대로 배치된 자체 그림을 가져요.",
    "Forged: the three pieces now have their own pictures, laid out as you assembled them; {n} fixed box(es).": "단조 완료: 세 부품이 이제 조립한 대로 배치된 자체 그림을 가져요. 틀 {n}개를 고정했어요.",
    "short pillar, medium pillar, tall pillar": "낮은 기둥, 중간 기둥, 높은 기둥",
    "medium pillar, tall pillar": "중간 기둥, 높은 기둥",
    "tall pillar": "높은 기둥",
    "short pillar": "낮은 기둥",
    "medium pillar": "중간 기둥",
    "Downloaded {n} files. Put them all in a folder named “{q}” inside Bigorna\\Mapas.": "파일 {n}개를 다운로드했어요. 모두 Bigorna\\Mapas 안의 “{Q}” 폴더에 넣으세요.",
    "Recalculate tier {n} from tier {n} with the game’s curve? Their current numbers are replaced.": "등급 {n}을(를) 등급 {n}에서 게임의 곡선으로 다시 계산할까요? 현재 수치는 바뀌어요.",
    "Recalculate tiers {n}–{n} from tier {n} with the game’s curve? Their current numbers are replaced.": "등급 {n}–{n}을(를) 등급 {n}에서 게임의 곡선으로 다시 계산할까요? 현재 수치는 바뀌어요.",
    "OK: first move all its triggers to another object (you click it), then delete.": "확인: 먼저 모든 트리거를 다른 오브젝트로 옮기고(그 오브젝트를 클릭하세요), 그다음 삭제해요.",
    "Cancel: delete anyway; the room stays without an opener until another object gets an “{q}” trigger.": "취소: 그래도 삭제해요. 다른 오브젝트가 “{Q}” 트리거를 받을 때까지 방을 여는 것이 없어요.",
    "This is the only trigger that opens room {n}.": "방 {n}을(를) 여는 유일한 트리거예요.",
    "Cancel: delete the trigger; the room stays without an opener until another object gets an “{q}” trigger.": "취소: 트리거를 삭제해요. 다른 오브젝트가 “{Q}” 트리거를 받을 때까지 방을 여는 것이 없어요.",
    "Removal trigger(s) added to “{q}”. Place the pillar again.": "“{Q}”에 제거 트리거를 추가했어요. 기둥을 다시 놓으세요.",
    "{n} trigger(s) or requirement(s) lose the counter.": "트리거나 요구 조건 {n}개가 카운터를 잃어요.",
    "Its consequence ({n} trigger(s)) goes too.": "그 결과(트리거 {n}개)도 함께 사라져요.",
    "Its map objective goes too.": "그 맵 목표도 함께 사라져요.",
    "{n} answer(s) or action(s) stop remembering it.": "답이나 행동 {n}개가 이것을 더 이상 기억하지 않아요.",
    "{n} card(s) or trigger requirement(s) lose this condition.": "카드나 트리거 요구 조건 {n}개가 이 조건을 잃어요.",
    "Room {n}: ready": "방 {n}: 준비됨",
    "ready": "준비됨",
    "no tiles": "타일 없음",
    "fewer than {n} hero spaces": "영웅 칸이 {n}개 미만",
    "no object opens this room": "이 방을 여는 오브젝트가 없음",
    "a workshop tile of this room no longer exists": "이 방의 워크숍 타일이 더 이상 없음",
    "\"{q}\" (level {n}) is not on tiles: from level {n} up a staircase stands on tiles": "\"{Q}\"({n}층)이(가) 타일 위에 있지 않아요. {n}층부터는 계단이 타일 위에 있어야 해요",
    "\"{q}\" is a workshop object that no longer exists": "\"{Q}\"은(는) 더 이상 없는 워크숍 오브젝트예요",
