    "\"{q}\": gives an item that is not in the workshop": "\"{Q}\": 워크숍에 없는 아이템을 줘요",
    "\"{q}\": every N rounds holds a skill test, a choice or another “{q}”: take it out": "\"{Q}\": N 라운드마다 능력치 테스트, 선택 또는 다른 “{Q}”을(를) 담고 있어요. 빼 주세요",
    "\"{q}\": remove monsters without a spawn group": "\"{Q}\": 출현 그룹 없이 몬스터 제거",
