    "\"{q}\": archways and bell frames cannot be clicked in the game, so their triggers never run": "\"{Q}\": 게임에서 아치와 종 틀은 클릭할 수 없어서 그 트리거는 절대 실행되지 않아요",
    "\"{q}\": requires an item that is not in the workshop": "\"{Q}\": 워크숍에 없는 아이템을 요구해요",
    "\"{q}\": requires a mission that no longer exists": "\"{Q}\": 더 이상 없는 임무를 요구해요",
    "The final mission is to defeat every monster, but there are none (Map setup).": "최종 임무는 모든 몬스터를 물리치는 것이지만 몬스터가 없어요 (맵 설정).",
    "The final mission is to defeat the monsters of room {n}, but it has none (Map setup).": "최종 임무는 방 {n}의 몬스터를 물리치는 것이지만 그 방에 몬스터가 없어요 (맵 설정).",
    "Counter “{q}” counts a monster that is no longer in the workshop (Counts button).": "카운터 “{Q}”이(가) 더 이상 워크숍에 없는 몬스터를 세요 (카운트 버튼).",
    "Counter “{q}” counts rounds by itself: set its Total (Counts button).": "카운터 “{Q}”은(는) 라운드를 스스로 세요. 합계를 정하세요 (카운트 버튼).",
    "Counter “{q}” counts monsters by itself: set its Total (Counts button).": "카운터 “{Q}”은(는) 몬스터를 스스로 세요. 합계를 정하세요 (카운트 버튼).",
