    "OGG, MP3 or WAV. Each file plays at its moment in the app: when the monster appears, when it activates, when a hero hits it and when it falls. A moment without a file stays silent. The files are exported next to the map.": "OGG, MP3 또는 WAV. 각 파일은 앱에서 정해진 순간에 재생돼요. 몬스터가 나타날 때, 활성화될 때, 영웅이 공격을 맞힐 때, 쓰러질 때예요. 파일이 없는 순간은 조용해요. 파일은 맵 옆에 내보내져요.",
