    "What it may change:": "바뀔 수 있는 것:",
    "What stays:": "그대로 유지되는 것:",
    "the intensity of the rooms with monsters and of the triggers that call monsters from the pool, all by the same step (from −6 to +6, always within 1 to 10);": "몬스터가 있는 방과 풀에서 몬스터를 부르는 트리거의 강도, 모두 같은 단계로 (−6부터 +6까지, 항상 1~10 범위 안에서);",
    "the tiers for 1–2, 3 and 4 heroes of the monsters placed by hand, by the game's rule (as ⚖ Balance on a monster).": "직접 놓은 몬스터의 영웅 1–2, 3, 4명용 등급, 게임 규칙에 따라 (몬스터의 ⚖ 균형처럼).",
    "the campaign progression, the monster and item pools, the monsters themselves, the objects, the triggers and the texts.": "캠페인 진행도, 몬스터 풀과 아이템 풀, 몬스터 자체, 오브젝트, 트리거, 텍스트.",
    "Work out the proposal": "제안 계산",
    "Simulating…": "시뮬레이션 중…",
    "No adjustment does better than the map as it is.": "지금 상태의 맵보다 나은 조정이 없어요.",
    "Now": "현재",
    "With the proposal": "제안 적용 시",
    "step": "단계",
    "What changes": "바뀌는 것",
    "Apply": "적용",
