    "Move to another room…": "다른 방으로 옮기기…",
    "None yet: use the Pillar tool on its sockets (level ${p.level} on the ribbon). Allowed here: medium pillar, tall pillar.": "아직 없어요. 소켓에 기둥 도구를 쓰세요 (리본의 ${p.level}층). 여기서 쓸 수 있는 것: 중간 기둥, 높은 기둥.",
    "None yet: use the Pillar tool on its sockets (level ${p.level} on the ribbon). Allowed here: short pillar, medium pillar, tall pillar.": "아직 없어요. 소켓에 기둥 도구를 쓰세요 (리본의 ${p.level}층). 여기서 쓸 수 있는 것: 낮은 기둥, 중간 기둥, 높은 기둥.",
    "None yet: use the Pillar tool on its sockets (level ${p.level} on the ribbon). Allowed here: tall pillar.": "아직 없어요. 소켓에 기둥 도구를 쓰세요 (리본의 ${p.level}층). 여기서 쓸 수 있는 것: 높은 기둥.",
