    "Music, scene, spawn pool, final mission, intro": "음악, 장면, 출현 풀, 최종 임무, 소개",
    "Name": "이름",
    "New rooms are born from an object: select it, add the trigger “{q}”. Pick a room here before touching what is in it.": "새 방은 오브젝트에서 태어나요. 오브젝트를 선택하고 “{Q}” 트리거를 추가하세요. 방 안의 것을 건드리기 전에 여기서 방을 고르세요.",
    "Room {n}: tile {n}B is elevated (level {n}) with no pillars.": "방 {n}: 타일 {n}B가 기둥 없이 높여져 있어요 ({n}층).",
    "Room {n}: tile {n}B is elevated with no pillars (warning)": "방 {n}: 타일 {n}B가 기둥 없이 높여져 있어요 (경고)",
    "Spawn pool of this room": "이 방의 출현 풀",
    "Visible from the start. The map introduction, music and final mission are in": "처음부터 보여요. 맵 소개, 음악, 최종 임무는 다음에 있어요:",
    "click a dim one to add it for this room only.": "흐린 몬스터를 클릭하면 이 방에만 추가돼요.",
