    "What the game would do": "게임이 할 일",
    "When the group is defeated": "그룹을 물리쳤을 때",
    "When the room starts, the game fills these spaces with its own rule for random spawns: points = intensity ÷ {n} × heroes × {n} × progression; it takes the highest tier of the map’s range the points pay for (costs {n}, {n}, {n}, {n}, {n}, {n}…), and monsters of the pool that have that tier enter, one per space (up to {n}), while the points last. Leftover points go to the next balanced room. All may enter, or just one strong monster.": "방이 시작되면 게임이 자체 무작위 출현 규칙으로 이 칸들을 채워요. 포인트 = 강도 ÷ {n} × 영웅 × {n} × 진행도. 포인트로 감당할 수 있는 맵 범위의 가장 높은 등급을 고르고(비용 {n}, {n}, {n}, {n}, {n}, {n}…), 그 등급을 가진 풀의 몬스터가 포인트가 남아 있는 동안 칸마다 한 마리씩(최대 {n}) 들어와요. 남은 포인트는 다음 균형 방으로 넘어가요. 모두 들어올 수도, 강한 몬스터 한 마리만 들어올 수도 있어요.",
    "change": "바꾸기",
    "it takes the highest tier of the map’s range the points pay for (costs {n}, {n}, {n}, {n}, {n}, {n}…), and monsters of the pool that have that tier enter, one per space (up to {n}), while the points last. Leftover points go to the next balanced room. All may enter, or just one strong monster.": "포인트로 감당할 수 있는 맵 범위의 가장 높은 등급을 고르고(비용 {n}, {n}, {n}, {n}, {n}, {n}…), 그 등급을 가진 풀의 몬스터가 포인트가 남아 있는 동안 칸마다 한 마리씩(최대 {n}) 들어와요. 남은 포인트는 다음 균형 방으로 넘어가요. 모두 들어올 수도, 강한 몬스터 한 마리만 들어올 수도 있어요.",
    "{n} (= spaces, default)": "{n} (= 칸 수, 기본값)",
