    "What the heroes find in it: a person, an object (the interaction tokens)": "영웅이 그 안에서 찾는 것: 사람, 물건 (상호작용 토큰)",
    "Tile {n} is in another room: reusing it here needs that room removed first": "타일 {n}은(는) 다른 방에 있어요. 여기서 다시 쓰려면 먼저 그 방을 제거해야 해요",
