    "A scene (dialogue boxes)": "장면 (대화창)",
    "A scene of dialogue boxes (like the story flow), your own film full screen, a sound effect of the game or your own sound file. (a scene, a video, a sound)": "대화창으로 된 장면(스토리 흐름처럼), 전체 화면으로 재생되는 직접 만든 영상, 게임 효과음 또는 직접 만든 소리 파일이에요. (장면, 동영상, 소리)",
    "A sound (game effect or your own file)": "소리 (게임 효과음 또는 직접 만든 파일)",
    "A tile": "타일",
    "A video (your own film)": "동영상 (직접 만든 영상)",
    "Add / Remove…": "추가 / 제거…",
    "Add a trigger to “{q}”": "“{Q}”에 트리거 추가",
