    "Add what?": "무엇을 추가할까요?",
    "Adds to (or removes from) the item pool or the monster spawn pool of the map, for the rest of the map. (item, monster spawn)": "맵의 나머지 동안 맵의 아이템 풀이나 몬스터 출현 풀에 추가하거나 제거해요. (아이템, 몬스터 출현)",
    "Add…": "추가…",
