    "Play a scene, video or sound": "장면, 동영상 또는 소리 재생",
    "Play what?": "무엇을 재생할까요?",
    "Puts something on the board, or takes it off, during play: tiles, objects, monsters, rooms. (a tile, an object, spawn monsters, a tile, a room, an object, a monster)": "플레이 중에 보드에 무언가를 놓거나 치워요. 타일, 오브젝트, 몬스터, 방이요. (타일, 오브젝트, 몬스터 출현, 타일, 방, 오브젝트, 몬스터)",
    "Remove…": "제거…",
    "Something appears on the board: a tile, an object or monsters. (a tile, an object, spawn monsters)": "보드에 무언가가 나타나요. 타일, 오브젝트 또는 몬스터요. (타일, 오브젝트, 몬스터 출현)",
    "Takes something off the board: a tile, a room, an object or monsters. (a tile, a room, an object, a monster)": "보드에서 무언가를 치워요. 타일, 방, 오브젝트 또는 몬스터요. (타일, 방, 오브젝트, 몬스터)",
    "What happens when a hero uses this object. Several triggers run in order.": "영웅이 이 오브젝트를 사용할 때 일어나는 일이에요. 여러 트리거가 순서대로 실행돼요.",
    "Puts something on the board, or takes it off, during play: tiles, objects, monsters, rooms. (a tile, an object, a tile, a room, an object, a monster)": "플레이 중에 보드에 무언가를 놓거나 치워요. 타일, 오브젝트, 몬스터, 방이요. (타일, 오브젝트, 타일, 방, 오브젝트, 몬스터)",
    "What happens once, when the count reaches {n} (the total of the counter). Several triggers run in order.": "카운트가 {n}(카운터의 합계)에 도달하면 한 번 일어나는 일이에요. 여러 트리거가 순서대로 실행돼요.",
    "When the balanced group is defeated: “{q}”": "균형 그룹을 물리치면: “{Q}”",
    "A goal on this map, announced when the monster is defeated and listed with the objectives. An objective does not end the map: the mission does (Map setup). An objective can be chosen there as the mission.": "이 맵의 목표예요. 몬스터가 쓰러지면 알려지고 목표 목록에 올라가요. 목표는 맵을 끝내지 않아요. 맵을 끝내는 것은 임무예요 (맵 설정). 그곳에서 목표를 임무로 고를 수 있어요.",
    "From when the monster is defeated, the round counter runs the triggers inside: every N rounds (as many times as you say, or to the end of the map), or once, N rounds later. For a wave, put “{q}” inside: the spawn has its own “{q}”.": "몬스터가 쓰러진 때부터 라운드 카운터가 안의 트리거를 실행해요. N 라운드마다(정한 횟수만큼, 또는 맵이 끝날 때까지) 또는 N 라운드 뒤에 한 번이요. 웨이브를 만들려면 안에 “{Q}”을(를) 넣으세요. 출현에는 자체 “{Q}”이(가) 있어요.",
    "When this monster is defeated: “{q}”": "이 몬스터가 쓰러지면: “{Q}”",
    "If the test fails: “{q}”": "테스트에 실패하면: “{Q}”",
