    "The six profiles of the game (class, weapons, skills and feats) go into the campaign. Each is played by the game’s hero (as in the game) or by a hero of your roster, put in it on the hero’s own sheet.": "게임의 여섯 프로필(직업, 무기, 기술, 업적)이 캠페인에 들어가요. 각 프로필은 게임의 영웅(게임처럼)이나 명단의 영웅이 맡으며, 영웅 자신의 시트에서 넣어요.",
