    "(the profile’s)": "(프로필의 것)",
    "Each weapon has one hero in the game (its parts, the shop, the inventory and the feats follow it). Picking the weapon of another hero hands him this one in exchange. The numbers come from the weapons: they are changed in the Weapons tab. The weapons belong to the profile: they stay with it if the hero leaves.": "게임에서 각 무기는 영웅 한 명의 것이에요 (부품, 상점, 창고, 업적이 따라가요). 다른 영웅의 무기를 고르면 그 영웅에게 이 무기를 대신 건네요. 수치는 무기에서 오며 무기 탭에서 바꿔요. 무기는 프로필에 속해서 영웅이 떠나도 프로필에 남아요.",
    "The weapons belong to the profile: they stay with it if the hero leaves.": "무기는 프로필에 속해서 영웅이 떠나도 프로필에 남아요.",
