    "Charms a hero carries; some have an effect the app applies. Only items listed in the workshop can be given by triggers, rewards and dialogues, dropped by monsters or crafted.": "영웅이 지니는 장신구예요. 일부는 앱이 적용하는 효과가 있어요. 트리거, 보상, 대화로 주거나, 몬스터가 떨어뜨리거나, 제작할 수 있는 것은 워크숍에 있는 아이템뿐이에요.",
    "Choose the type first: it decides the figure and the animated art in the app (the game has no others) and the behaviour rules of that family. Then the rest of the sheet opens.": "먼저 유형을 고르세요. 유형이 앱에서의 피규어와 움직이는 아트(게임에 다른 것은 없어요), 그리고 그 계열의 행동 규칙을 정해요. 그다음 시트의 나머지가 열려요.",
