    "Drag the pieces to put the weapon together as you want it": "조각을 끌어 원하는 대로 무기를 조립하세요",
    "Drag the pieces to put the weapon together as you want it; the wheel (or the slider) changes the size of the chosen piece, Shift+wheel, Q/E or the turn slider rotate it, the arrows nudge it. A piece only shows inside its own box: what goes out of it is cut (shown faint).": "조각을 끌어 원하는 대로 무기를 조립하세요. 휠(또는 슬라이더)로 고른 조각의 크기를 바꾸고, Shift+휠, Q/E 또는 회전 슬라이더로 돌리고, 화살표로 미세 이동해요. 조각은 자기 틀 안에서만 보여요. 틀 밖으로 나간 부분은 잘려요 (흐리게 보여요).",
    "Drag the pieces to put the weapon together, forge the template and bake the pictures": "조각을 끌어 무기를 조립하고, 템플릿을 단조하고, 그림을 구워 내세요",
