    "Pick a kind of weapon, then its heads, hafts or grips. What you change applies while this map is played (to every copy of the part, also the ones bought or found later)": "무기 종류를 고른 다음 머리, 자루, 손잡이를 고르세요. 바꾼 것은 이 맵을 플레이하는 동안 적용돼요(부품의 모든 사본, 나중에 사거나 찾은 것도 포함)",
    "Pick a kind of weapon, then its heads, hafts or grips. What you change applies while this map is played (to every copy of the part, also the ones bought or found later); what you leave stays as in the game.": "무기 종류를 고른 다음 머리, 자루, 손잡이를 고르세요. 바꾼 것은 이 맵을 플레이하는 동안 적용되고(부품의 모든 사본, 나중에 사거나 찾은 것도 포함), 그대로 둔 것은 게임과 같아요.",
