    "Portrait in the story boxes (speaker and cast). Transparent PNG of the bust, {n} px or more, looks best.": "스토리 대화창의 초상화예요 (말하는 사람과 등장인물). 흉상의 투명 PNG, {n} px 이상이 가장 보기 좋아요.",
    "Potions and one-use cards the heroes spend during a quest. Only items listed in the workshop can be given by triggers, rewards and dialogues, dropped by monsters or crafted.": "영웅이 퀘스트 중에 쓰는 물약과 일회용 카드예요. 트리거, 보상, 대화로 주거나, 몬스터가 떨어뜨리거나, 제작할 수 있는 것은 워크숍에 있는 아이템뿐이에요.",
    "Preview": "미리 보기",
    "Price of the recipe (gold)": "제작법 가격 (골드)",
    "Put it in the round frame, like the game’s": "게임처럼 둥근 틀에 넣기",
    "Range": "사정거리",
    "Rarity": "희귀도",
    "Recalculate the other tiers from this one with the game's own curve: health grows ×{n}, ×{n}, ×{n}, ×{n}, ×{n}, ×{n}, ×{n} per tier, defense +{n} per tier, attack +{n} up to tier {n} and then +{n} every two tiers. With this tier alone, it creates the tiers up to {n}": "게임 자체의 곡선으로 이 등급에서 다른 등급을 다시 계산해요. 체력은 등급마다 ×{n}, ×{n}, ×{n}, ×{n}, ×{n}, ×{n}, ×{n}씩 늘고, 방어는 등급마다 +{n}, 공격은 +{n}(등급 {n}까지), 그 뒤로는 두 등급마다 +{n}이에요. 이 등급만 있으면 등급 {n}까지 만들어요",
    "Recipe: (no item yet)": "제작법: (아직 아이템 없음)",
