    "Show the boxes": "틀 보기",
    "Shown on the hero tabs, the hero choice and the hero screens. Square, {n} px or more. The strip shown in the shop and inventory is cut from the upper middle of it.": "영웅 탭, 영웅 선택, 영웅 화면에 보여요. 정사각형, {n} px 이상. 상점과 창고에 보이는 띠는 그림의 위쪽 가운데에서 잘라요.",
    "Shown on the monster tab in the app and in this editor. Square, {n} px or more.": "앱의 몬스터 탭과 이 편집기에 보여요. 정사각형, {n} px 이상.",
