    "Strong items early make the fights easy": "초반에 강한 아이템을 주면 전투가 쉬워져요",
    "Strong items early make the fights easy; too few, or weak ones, leave the heroes behind the monsters. Pick them on purpose, thinking of the heroes' progress along the map.": "초반에 강한 아이템을 주면 전투가 쉬워지고, 너무 적거나 약하면 영웅이 몬스터에게 뒤처져요. 맵 동안 영웅의 성장을 생각하며 신중하게 고르세요.",
