    "The animated figure of the monster chosen in Behaviour.": "행동 방식에서 고른 몬스터의 움직이는 피규어예요.",
    "The app applies the effect of this game item": "앱이 이 게임 아이템의 효과를 적용해요",
    "The app shows this text when it triggers": "발동하면 앱이 이 텍스트를 보여 줘요",
    "The app shows this text when it triggers; the players apply it.": "발동하면 앱이 이 텍스트를 보여 주고, 플레이어가 적용해요.",
    "The behaviour monster’s rule: none, the players apply the text at the table.": "행동 기준 몬스터의 규칙: 없음, 플레이어가 테이블에서 텍스트를 적용해요.",
    "The box of this piece follows where you left it (the template changes)": "이 조각의 틀이 놓아 둔 곳을 따라가요 (템플릿이 바뀌어요)",
    "The boxes of the game, each piece fitted in its own": "게임의 틀, 각 조각을 자기 틀에 맞춤",
    "The game's sound for that kind of monster, when it appears and when it attacks.": "그 종류의 몬스터가 나타날 때와 공격할 때의 게임 소리예요.",
    "The hero has": "영웅이 가진 것:",
    "The material’s picture in the app. Square, {n} px or more.": "앱에서의 재료 그림이에요. 정사각형, {n} px 이상.",
    "The monster eyes the weakest hero…": "몬스터가 가장 약한 영웅을 노려봐요…",
    "The monster has": "몬스터가 가진 것:",
    "The monster’s own rule shown in the attack window, like the bandit’s “{q}”. Leave empty to keep the one of the behaviour monster.": "도적의 “{Q}”처럼 공격 창에 보이는 몬스터 자체 규칙이에요. 행동 기준 몬스터의 규칙을 유지하려면 비워 두세요.",
    "The party has it from the start of the map (the heroes pick it in the hero choice)": "파티가 맵 시작부터 가지고 있어요 (영웅 선택에서 영웅들이 골라요)",
    "The party knows it from the start": "파티가 처음부터 알고 있음",
    "The piece as drawn in the weapon. Transparent PNG, ideally the same shape as the game’s (": "무기에 그려진 조각이에요. 투명 PNG, 게임과 같은 모양이면 가장 좋아요 (",
    "The piece as drawn in the weapon. Transparent PNG, ideally the same shape as the game’s.": "무기에 그려진 조각이에요. 투명 PNG, 게임과 같은 모양이면 가장 좋아요.",
    "The quest ends in": "퀘스트 결과:",
