    "What the monster does on its turn, in order; “{q}” chains them. Speed, damage, aim, attack, range, healing, shield, initiative and range type are the numbers the app uses; the text is what the players read.": "몬스터가 자기 차례에 하는 일, 순서대로예요. “{Q}”이(가) 이것들을 이어요. 속도, 피해, 조준, 공격, 사정거리, 치유, 보호막, 우선권, 사정거리 유형은 앱이 쓰는 수치이고, 텍스트는 플레이어가 읽는 것이에요.",
    "When a monster is defeated": "몬스터를 물리쳤을 때",
