    "With these weapons": "다음 무기로",
    "Worn by a hero: a card with its rule, kept in the party’s inventory. Only items listed in the workshop can be given by triggers, rewards and dialogues, dropped by monsters or crafted.": "영웅이 착용해요. 규칙이 적힌 카드로, 파티의 창고에 보관돼요. 트리거, 보상, 대화로 주거나, 몬스터가 떨어뜨리거나, 제작할 수 있는 것은 워크숍에 있는 아이템뿐이에요.",
    "Write plain text. The buttons put in the names the app fills in ([monster] = the name of this monster, [hero] = the name of the hero it targets (or another name the app fills in)) and the game icons. Rule words like scar, terrify or focus become the game’s highlighted terms by themselves.": "일반 텍스트로 쓰세요. 버튼은 앱이 채우는 이름([monster] = 이 몬스터의 이름, [hero] = 노리는 영웅의 이름(또는 앱이 채우는 다른 이름))과 게임 아이콘을 넣어요. 상처, 공포, 집중 같은 규칙 용어는 스스로 게임의 강조 용어가 돼요.",
    "a major injury": "큰 부상",
