    "Boxes play in the order of the arrows, starting at the first. A question box branches: each answer leads to its own next box. A video box plays your own film (MP{n} or WebM) between the other boxes.": "대화창은 첫 번째부터 화살표 순서대로 재생돼요. 질문 대화창은 분기해요. 각 답이 자기 다음 대화창으로 이어져요. 동영상 대화창은 다른 대화창 사이에 직접 만든 영상(MP{n} 또는 WebM)을 재생해요.",
