    "the bell hangs in its frame: a bell on the table takes the bell frame, and with one frame only one bell hangs at a time": "종은 종 틀에 걸려요. 테이블의 종은 종 틀을 쓰고, 틀이 하나면 한 번에 종 하나만 걸려요",
