    "Erase the campaign, all its maps and its workshop from the editor": "편집기에서 캠페인, 모든 맵, 워크숍을 지워요",
    "Every map, side quest and waypoint has a place here and a marker kind: main quest, side quest, narrative event or city visit.": "모든 맵, 보조 퀘스트, 경유지는 여기에 자리와 마커 종류가 있어요. 주요 퀘스트, 보조 퀘스트, 이야기 전개 이벤트, 도시 방문이요.",
    "Everything of this campaign is erased from the editor, and it cannot be undone:": "이 캠페인의 모든 것이 편집기에서 지워지며, 되돌릴 수 없어요:",
    "Export campaign": "캠페인 내보내기",
    "Export, then delete": "내보낸 뒤 삭제",
    "Files already exported stay in the folder": "이미 내보낸 파일은 폴더에 남아요",
    "Files already exported stay in the folder; delete them there if you want. Autosave stops following this campaign, so it will not erase them. The game keeps the progress of any party that played it.": "이미 내보낸 파일은 폴더에 남아요. 원하면 그곳에서 삭제하세요. 자동 저장은 이 캠페인을 더 이상 따라가지 않으니 파일을 지우지 않아요. 게임은 이 캠페인을 플레이한 모든 파티의 진행 상황을 보관해요.",
