    "Narrative event": "이야기 전개 이벤트",
    "Narrative event (a marker on the world map)": "이야기 전개 이벤트 (세계 지도의 마커)",
    "Narrative event (plays at its point of the story)": "이야기 전개 이벤트 (스토리의 해당 지점에서 재생)",
    "New variable (Spared the bandit, Sided with the rebels…)": "새 변수 (도적을 살려 줬다, 반란군 편에 섰다…)",
    "No remembered choice yet: in a question box, tick “{q}”.": "아직 기억된 선택이 없어요. 질문 대화창에서 “{Q}”에 체크하세요.",
    "On the world map as": "세계 지도에서의 표시",
    "PNG or JPG, {n}:{n} ({n}×{n} fits exactly). It covers the whole frame the game shows": "PNG 또는 JPG, {n}:{n} ({n}×{n}이면 딱 맞아요). 게임이 보여 주는 틀 전체를 덮어요",
    "PNG or JPG, {n}:{n} ({n}×{n} fits exactly). It covers the whole frame the game shows; the game's water, burnt land, place names and roads are hidden. The mist covers a fixed region of the game's own map (the Mistlands).": "PNG 또는 JPG, {n}:{n} ({n}×{n}이면 딱 맞아요). 게임이 보여 주는 틀 전체를 덮으며, 게임의 물, 불탄 땅, 지명, 길은 숨겨져요. 안개는 게임 자체 지도의 고정된 지역(안개 지대)을 덮어요.",
    "Place this waypoint on the world map": "이 경유지를 세계 지도에 배치",
    "Plays as": "재생 방식",
    "Point at a line to light its arrow. To see where a card leads, click its ●.": "선을 가리키면 화살표가 빛나요. 카드가 이어지는 곳을 보려면 ●를 클릭하세요.",
    "Remember a choice": "선택 기억하기",
    "Remember this answer": "이 답 기억하기",
    "Remove this arrow": "이 화살표 제거",
    "Rename: every answer, card and map trigger that uses it follows": "이름 바꾸기: 이것을 쓰는 모든 답, 카드, 맵 트리거가 따라 바뀌어요",
    "Rewards on completion": "완료 보상",
    "Scene {n}": "장면 {n}",
    "Set by": "정하는 것",
    "Side quest": "보조 퀘스트",
    "Side quest {n}": "보조 퀘스트 {n}",
    "Simulation": "시뮬레이션",
    "Stay and fill them": "남아서 채우기",
    "Story flow": "스토리 흐름",
    "The choices the campaign remembers from one map to the next: spared the bandit, sided with the rebels, took the cursed ring… A choice is set when the party picks an answer ticked “{q}” (or by a “{q}” action) and stays for the rest of the campaign. Cards of the story flow and triggers of the maps can then happen only if the party made it, or did not.": "캠페인이 맵에서 맵으로 기억하는 선택이에요. 도적을 살려 줬다, 반란군 편에 섰다, 저주받은 반지를 가져갔다… 선택은 파티가 “{Q}”에 체크한 답을 고를 때(또는 “{Q}” 행동으로) 정해지고 캠페인 끝까지 남아요. 그러면 스토리 흐름의 카드와 맵의 트리거는 파티가 그 선택을 했을 때만, 또는 하지 않았을 때만 일어나게 할 수 있어요.",
    "The party moves on the world map (it goes after the selected card)": "파티가 세계 지도에서 이동해요 (선택한 카드 뒤에 들어가요)",
    "The scene goes on with the next box when the film ends.": "영상이 끝나면 장면이 다음 대화창으로 이어져요.",
    "Then:": "그다음:",
    "They are exported as they are. Fill them, or delete the ones you do not need.": "있는 그대로 내보내져요. 채우거나 필요 없는 것을 삭제하세요.",
    "Type the name of the campaign to confirm:": "확인하려면 캠페인 이름을 입력하세요:",
    "Unlock a map or waypoint": "맵이나 경유지 잠금 해제",
    "Use my own city picture…": "직접 만든 도시 그림 사용…",
    "Use my own world map…": "직접 만든 세계 지도 사용…",
    "Used by": "사용하는 것",
    "Video (your own film)": "동영상 (직접 만든 영상)",
