    "World map position: -{n}, {n}.": "세계 지도 위치: -{n}, {n}.",
    "World map position: {n}, {n}.": "세계 지도 위치: {n}, {n}.",
    "Write the boxes of this scene": "이 장면의 대화창 쓰기",
    "Write the boxes ▸": "대화창 쓰기 ▸",
    "Writes the .bcamp and its maps (download), then deletes.": ".bcamp와 그 맵들을 써서(다운로드) 저장한 다음 삭제해요.",
    "You are building the rooms of this map. Pick another map, or add maps, waypoints and dialogues, on the campaign screen (“{q}” above).": "이 맵의 방을 만드는 중이에요. 다른 맵을 고르거나 맵, 경유지, 대화를 추가하려면 캠페인 화면으로 가세요 (위의 “{Q}”).",
    "after Map {n}": "맵 {n} 뒤",
    "after Side quest {n}": "보조 퀘스트 {n} 뒤",
    "after Waypoint {n}": "경유지 {n} 뒤",
    "after a waypoint it plays on arrival": "경유지 뒤에서는 도착할 때 재생돼요",
    "arrows nudge the selected card (or the view)": "화살표로 선택한 카드(또는 화면)를 미세 이동",
    "before anything it opens the campaign.": "맨 앞에 있으면 캠페인을 열어요.",
    "campaign progression {n} (Map setup → Balancing).": "캠페인 진행도 {n} (맵 설정 → 균형).",
    "double-click the background adds a box": "배경을 더블클릭하면 대화창 추가",
