    "end of the scene": "장면의 끝",
    "faded dots are the official destinations": "흐린 점은 공식 목적지예요",
    "from the start": "처음부터",
    "map {n} of {n}": "맵 {n}/{n}",
    "narrator": "서술자",
    "nothing depends on it yet: pick it in “{q}” of a card, or as the requirement “{q}” of a map trigger.": "아직 이것에 따르는 것이 없어요. 카드의 “{Q}”에서 고르거나, 맵 트리거의 요구 조건 “{Q}”(으)로 고르세요.",
    "nothing sets it yet: tick “{q}” in a question box and give it this name. Until then “{q}” is never true.": "아직 이것을 정하는 것이 없어요. 질문 대화창에서 “{Q}”에 체크하고 이 이름을 주세요. 그때까지 “{Q}”은(는) 절대 참이 되지 않아요.",
    "only a question may branch": "분기는 질문만 할 수 있어요",
    "progression {n}": "진행도 {n}",
    "question": "질문",
    "the name is yours.": "이름은 자유롭게 정해요.",
    "the scenes that follow it play in the same visit.": "그 뒤의 장면은 같은 방문에서 재생돼요.",
    "the story flow: {n} card(s), {n} scene(s) with their boxes, {n} story variable(s)": "스토리 흐름: 카드 {n}장, 대화창이 있는 장면 {n}개, 스토리 변수 {n}개",
    "the workshop: {n} monster(s), {n} NPC(s), {n} item(s), {n} hero(es), {n} weapon(s), {n} recipe(s), {n} feat(s), {n} tile(s)/object(s) of your own": "워크숍: 몬스터 {n}, NPC {n}, 아이템 {n}, 영웅 {n}, 무기 {n}, 제작법 {n}, 업적 {n}, 직접 만든 타일/오브젝트 {n}",
    "the world map positions, the rewards, the music and videos chosen": "세계 지도 위치, 보상, 고른 음악과 동영상",
    "with your own map picture, draw the roads on the left": "직접 만든 지도 그림을 쓴다면 왼쪽에서 길을 그리세요",
    "without a name": "이름 없음",
    "{n} box(es): text, questions and videos (your own films), played one after the other in the same frame. Played at this point of the story: after a map it is the map’s closing scene": "대화창 {n}개: 텍스트, 질문, 동영상(직접 만든 영상)을 같은 틀에서 차례로 재생해요. 스토리의 이 지점에서 재생돼요. 맵 뒤에서는 맵의 마무리 장면이에요",
    "{n} box(es): text, questions and videos (your own films), played one after the other in the same frame. Played at this point of the story: after a map it is the map’s closing scene; after a waypoint it plays on arrival; before anything it opens the campaign.": "대화창 {n}개: 텍스트, 질문, 동영상(직접 만든 영상)을 같은 틀에서 차례로 재생해요. 스토리의 이 지점에서 재생돼요. 맵 뒤에서는 맵의 마무리 장면이고, 경유지 뒤에서는 도착할 때 재생되며, 맨 앞에 있으면 캠페인을 열어요.",
    "{n} room(s)": "방 {n}개",
