    "The original maps of the game are read by the Bigorna mod from your own copy of the game: start the game once with the mod installed (the title screen prepares them), then open the editor from the Editor folder of the game again.": "게임의 원본 맵은 Bigorna 모드가 내 게임 사본에서 읽어요. 모드를 설치한 상태로 게임을 한 번 시작한 다음(타이틀 화면이 맵을 준비해요), 게임의 Editor 폴더에서 편집기를 다시 여세요.",
    "The quests of the game, converted into maps of the editor: tiles, objects, rooms, monsters and the logic the triggers can say.": "편집기 맵으로 변환한 게임의 퀘스트예요. 타일, 오브젝트, 방, 몬스터, 그리고 트리거로 나타낼 수 있는 로직이요.",
    "Each map comes with notes on what was simplified (Map setup).": "각 맵에는 단순화한 부분에 대한 메모가 있어요 (맵 설정).",
