    "Click the object or monster that will open the new room: it gets the trigger “Open a room”. Esc cancels.": "새 방을 열 오브젝트나 몬스터를 클릭하세요. “방 열기” 트리거를 받아요. Esc로 취소해요.",
    "Click an object or a monster of the map (staircases and bridges are floor).": "맵의 오브젝트나 몬스터를 클릭하세요 (계단과 다리는 바닥이에요).",
