    "The one you pick appears on the board, framed and marked “preview” in the list of rooms, so you see it in place.": "고른 후보는 보드에 나타나 틀로 둘러싸이고 방 목록에 “미리 보기”로 표시돼서, 제자리에서 볼 수 있어요.",
