    "This belongs to the package": "이것은 패키지에 속해요",
    "Change it: a version of yours, with a new ID": "바꾸기: 새 ID로 된 내 버전",
    "Create a clone": "클론 만들기",
    "The package’s entry stays as the creator made it.": "패키지의 항목은 제작자가 만든 그대로 남아요.",
    "Clone made: it is yours to change.": "클론을 만들었어요. 마음대로 바꿔도 돼요.",
    "Now this version is yours, with a new ID: change it here.": "이제 이 버전은 새 ID로 된 내 것이에요. 여기서 바꾸세요.",
    "An original of the game: it stays as the game has it.": "게임의 원본이에요. 게임에 있는 그대로 남아요.",
    "Change it here: changed, it becomes yours, with the same id (what uses it gets your version; the package’s file stays as it is). To take it out, remove the package (📚 My packages).": "여기서 바꾸세요. 바꾸면 같은 id로 내 것이 돼요 (이것을 쓰는 것은 내 버전을 받고, 패키지 파일은 그대로 남아요). 빼려면 패키지를 제거하세요 (📚 내 패키지).",
    "It replaces the map on screen, fully editable.": "화면의 맵을 대체하며, 모두 편집할 수 있어요.",
    "A whole map: why the heroes go in (premise), what they must do to win (objective), what changes along the way (extra rule), how the tension grows and the end. It replaces the map on screen, fully editable.": "맵 전체예요. 영웅이 들어가는 이유(전제), 이기려면 해야 할 일(목표), 도중에 바뀌는 것(추가 규칙), 긴장이 고조되는 방식, 결말이요. 화면의 맵을 대체하며, 모두 편집할 수 있어요.",
    "Add to the campaign": "캠페인에 추가",
    "Monsters in a room": "방의 몬스터",
    "A long, narrow way: whoever holds the narrow part holds the room.": "길고 좁은 길이에요. 좁은 곳을 지키는 쪽이 방을 지배해요.",
    "Wide and open: a straight fight with room to move.": "넓고 탁 트인 곳이에요. 움직일 공간이 있는 정면 대결이에요.",
    "Few or no monsters, several points of interest to search and a clue.": "몬스터가 적거나 없고, 뒤질 관심 지점 여러 개와 단서가 있어요.",
    "The reward, guarded or not: chests at the back, a price to reach them.": "지켜지거나 지켜지지 않는 보상이에요. 안쪽의 상자, 그곳에 닿기 위한 대가가 있어요.",
    "A calm place to breathe, heal and talk: no monsters, a little to find.": "숨을 돌리고, 치유하고, 이야기하는 조용한 곳이에요. 몬스터는 없고 찾을 것이 조금 있어요.",
    "The last room: large, with cover and a strong foe at the back.": "마지막 방이에요. 크고, 엄폐물이 있으며, 안쪽에 강한 적이 있어요.",
    "The way is blocked by water, fire or rubble: go around, or through it.": "물, 불, 잔해로 길이 막혀 있어요. 돌아가거나 뚫고 지나가세요.",
    "A raised platform over the floor: whoever holds the height sees everything.": "바닥 위로 높인 플랫폼이에요. 높은 곳을 차지하는 쪽이 모든 것을 봐요.",
    "Moving: drag the room · R turns it · Esc or a click outside ends it": "이동 중: 방을 끌어 옮기세요 · R로 회전 · Esc나 바깥 클릭으로 끝내요",
    "Click the outline to move the room · R turns it": "윤곽선을 클릭해서 방 옮기기 · R로 회전",
    "The room has no tiles to turn.": "방에 돌릴 타일이 없어요.",
    "Turned, the room overlapped another one: it stayed as it was.": "돌리면 방이 다른 방과 겹쳐서 그대로 두었어요.",
    "Room turned 90°, with everything in it.": "방을 안의 모든 것과 함께 90° 돌렸어요.",
    "Delete anyway": "그래도 삭제",
    "First move all its triggers to another object (you click it), then delete.": "먼저 모든 트리거를 다른 오브젝트로 옮기고(그 오브젝트를 클릭하세요), 그다음 삭제해요.",
    "The room stays without an opener until another object opens it.": "다른 오브젝트가 방을 열 때까지 방을 여는 것이 없어요.",
    "Picture in the scenes": "장면에서의 그림",
    "An NPC of the game: the game shows its own picture in the scenes.": "게임의 NPC예요. 장면에서는 게임이 자체 그림을 보여 줘요.",
