    "This erases everything the editor keeps: the map or campaign on screen, the Workshop (monsters, items, materials, objects, imported or made), the packages (in the app: the Pacotes folder, every package in it), the pictures kept by the editor, the quick save, your archetypes, the hints and warnings, window positions and sizes, the author, the export folder and the autosave.": "편집기가 보관하는 모든 것을 지워요. 화면의 맵이나 캠페인, 워크숍(가져오거나 만든 몬스터, 아이템, 재료, 오브젝트), 패키지(앱에서는 Pacotes 폴더와 그 안의 모든 패키지), 편집기가 보관한 그림, 빠른 저장, 나만의 원형, 힌트와 경고, 창 위치와 크기, 제작자, 내보내기 폴더, 자동 저장이요.",
    "Reset everything: the work on screen, the Workshop and the packages, the pictures kept, the quick save, archetypes, tips and warnings, window positions and sizes, author, export folder and autosave. The language stays.": "모두 초기화: 화면의 작업, 워크숍과 패키지, 보관한 그림, 빠른 저장, 원형, 팁과 경고, 창 위치와 크기, 제작자, 내보내기 폴더, 자동 저장. 언어는 유지돼요.",
