    "No feat defined: the game offers this hero its own feats. Add feats to choose them (any feat, from any hero).": "정한 업적이 없어요. 게임이 이 영웅에게 자체 업적을 제안해요. 고르려면 업적을 추가하세요 (어느 영웅의 업적이든 돼요).",
