    "Damage from weaknesses beyond the monster’s health, in total": "몬스터의 체력을 넘어선 약점 피해, 합계",
    "Rounds in which it happens a number of times": "일정 횟수 일어난 라운드",
    "Rounds in a row in which it happens": "연속으로 일어난 라운드",
